findings.codeql_raw_query:
/**
 * @name Zip path traversal vulnerability
 * @description Extracting zip files without validating paths can lead to directory traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module ZipPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is when zipfile.ZipFile.extract or similar methods are called with untrusted paths
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipPathTraversalFlow = TaintTracking::Global<ZipPathTraversalConfig>;
import ZipPathTraversalFlow::PathGraph

from ZipPathTraversalFlow::PathNode source, ZipPathTraversalFlow::PathNode sink
where ZipPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
